import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"]
    cdc_events = inputs["cdc_events"]

    # 1. At-least-once delivery -> distinct by seq (keep first occurrence)
    cdc = cdc_events.drop_duplicates(subset="seq", keep="first").copy()

    # Build initial per-order state from target_state
    target_dict = {}
    for row in target_state.itertuples(index=False):
        target_dict[row.order_id] = {
            "status": row.status,
            "amount": row.amount,
            "last_seq": row.last_seq,
        }

    all_order_ids = set(target_dict.keys()) | set(cdc["order_id"].unique().tolist())

    events_by_order = {}
    if not cdc.empty:
        for oid, grp in cdc.groupby("order_id"):
            events_by_order[oid] = grp.sort_values("seq")

    new_state_rows = []
    tombstone_rows = []

    for oid in all_order_ids:
        orig = target_dict.get(oid)
        current_exists = orig is not None
        ever_had_row = current_exists

        if current_exists:
            current_status = orig["status"]
            current_amount = orig["amount"]
            current_last_seq = orig["last_seq"]
        else:
            current_status = None
            current_amount = np.nan
            current_last_seq = None

        evs = events_by_order.get(oid)
        last_op = None
        last_seq_applied = None

        if evs is not None:
            if current_exists:
                guard_last_seq = orig["last_seq"]
                evs = evs[evs["seq"] > guard_last_seq]
            # else: no guard, all events apply

            for ev in evs.itertuples(index=False):
                seq = ev.seq
                op = ev.op

                if op in ("I", "U"):
                    if not current_exists:
                        # creating a fresh row: amount taken as-is
                        current_exists = True
                        ever_had_row = True
                        current_status = ev.status
                        current_amount = ev.amount
                        current_last_seq = seq
                    else:
                        current_status = ev.status
                        if op == "U" and pd.isna(ev.amount):
                            # 'U' with NULL amount leaves existing amount unchanged
                            pass
                        else:
                            current_amount = ev.amount
                        current_last_seq = seq
                    last_op = op
                    last_seq_applied = seq
                elif op == "D":
                    if current_exists:
                        current_exists = False
                    last_op = "D"
                    last_seq_applied = seq

        if current_exists:
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": current_status,
                    "amount": current_amount,
                    "last_seq": current_last_seq,
                }
            )

        if ever_had_row and last_op == "D":
            tombstone_rows.append(
                {
                    "order_id": oid,
                    "deleted_seq": last_seq_applied,
                }
            )

    new_state_df = pd.DataFrame(
        new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
    )
    tombstones_df = pd.DataFrame(
        tombstone_rows, columns=["order_id", "deleted_seq"]
    )

    if not new_state_df.empty:
        new_state_df["order_id"] = new_state_df["order_id"].astype("int64")
        new_state_df["last_seq"] = new_state_df["last_seq"].astype("int64")
        new_state_df["amount"] = new_state_df["amount"].astype("float64")
        new_state_df["status"] = new_state_df["status"].astype(object)
    else:
        new_state_df = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "status": pd.Series(dtype="object"),
                "amount": pd.Series(dtype="float64"),
                "last_seq": pd.Series(dtype="int64"),
            }
        )

    if not tombstones_df.empty:
        tombstones_df["order_id"] = tombstones_df["order_id"].astype("int64")
        tombstones_df["deleted_seq"] = tombstones_df["deleted_seq"].astype("int64")
    else:
        tombstones_df = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "deleted_seq": pd.Series(dtype="int64"),
            }
        )

    return {"new_state": new_state_df, "tombstones": tombstones_df}
